// Turns the versioned prompts of prompts/**/*.md into lib/ai/prompts.generated.ts, so the Workers runtime (which has no file system) can read them.
// The Markdown files stay the ONLY source: this file is derived, never edited by hand, and a test fails when it is out of date (lib/ai/prompts.test.ts).
//   node scripts/generate-prompts.mjs            writes lib/ai/prompts.generated.ts
//   node scripts/generate-prompts.mjs --check    exits 1 when the generated file is not what the prompts produce
// No dependency: the header is plain `key: value` lines and the instructions are the "## Instrucciones del sistema" section.
import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, relative } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const ROOT = join(fileURLToPath(new URL(".", import.meta.url)), "..");
const OUT = "lib/ai/prompts.generated.ts";
const SECTION = "## Instrucciones del sistema";

function promptFiles(dir, base) {
  const found = [];
  for (const entry of readdirSync(join(base, dir), { withFileTypes: true })) {
    const path = `${dir}/${entry.name}`;
    if (entry.isDirectory()) {
      if (entry.name !== "evals") found.push(...promptFiles(path, base));
    } else if (entry.name.endsWith(".md") && entry.name !== "README.md" && !entry.name.startsWith("_")) found.push(path);
  }
  return found;
}

/** One prompt file as the generated module keeps it: its header and the text of its system instructions. */
export function readPrompt(source, text) {
  const normalized = text.replace(/\r\n/g, "\n");
  const header = /^---\n([\s\S]*?)\n---\n/.exec(normalized);
  if (!header) throw new Error(`${source}: no header`);
  const field = (name) => new RegExp(`^${name}:\\s*(.+)$`, "m").exec(header[1])?.[1].trim().replace(/^"|"$/g, "");
  const id = field("id");
  const version = field("version");
  const status = field("status");
  if (!id || !version || !status) throw new Error(`${source}: id, version and status are required`);
  const body = normalized.slice(header[0].length);
  const start = body.indexOf(`${SECTION}\n`);
  if (start < 0) throw new Error(`${source}: no "${SECTION}" section`);
  const rest = body.slice(start + SECTION.length + 1);
  const end = rest.search(/^## /m);
  const instructions = (end < 0 ? rest : rest.slice(0, end)).trim();
  if (instructions === "") throw new Error(`${source}: the system instructions are empty`);
  return { id, version, status, source, instructions };
}

/** The text of lib/ai/prompts.generated.ts for the prompts under `root`. Deterministic: sorted by id, LF line endings. */
export function buildPromptsModule(root = ROOT) {
  const entries = promptFiles("prompts", root)
    .sort()
    .map((source) => readPrompt(source, readFileSync(join(root, source), "utf8")))
    .sort((a, b) => a.id.localeCompare(b.id));
  const ids = new Set();
  for (const entry of entries) {
    if (ids.has(entry.id)) throw new Error(`duplicate prompt id ${entry.id}`);
    ids.add(entry.id);
  }
  const lines = [
    "// GENERATED by scripts/generate-prompts.mjs from prompts/**/*.md. Do not edit: change the prompt and run `npm run prompts:generate`.",
    "// The Markdown files are the source of truth (rules/ai.md 3); lib/ai/prompts.test.ts fails when this file is out of date.",
    "",
    "export type GeneratedPrompt = { readonly version: string; readonly status: string; readonly source: string; readonly instructions: string };",
    "",
    "export const PROMPTS: Readonly<Record<string, GeneratedPrompt>> = {",
    ...entries.map((entry) => `  ${JSON.stringify(entry.id)}: { version: ${JSON.stringify(entry.version)}, status: ${JSON.stringify(entry.status)}, source: ${JSON.stringify(entry.source)}, instructions: ${JSON.stringify(entry.instructions)} },`),
    "};",
    "",
  ];
  return lines.join("\n");
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const expected = buildPromptsModule();
  const target = join(ROOT, OUT);
  if (process.argv.includes("--check")) {
    const current = existsSync(target) ? readFileSync(target, "utf8").replace(/\r\n/g, "\n") : "";
    if (current !== expected) {
      console.error(`${relative(ROOT, target)} is out of date: run npm run prompts:generate`);
      process.exit(1);
    }
    process.stdout.write(`${OUT} is up to date\n`);
  } else {
    writeFileSync(target, expected);
    process.stdout.write(`wrote ${OUT}\n`);
  }
}
